self.KB_CONTENT["card:757107"]={"id":"card:757107","ty":"card","sourceId":"757107","title":"『庫存異動統計表』中的『類別 (INV.MB005~INV.MB008)』為何？","ver":"iGP","topic":"統計表","keywords":["統計表","品號","庫存","異動"],"y":"other","answer":"* 可複選(icon)或[F2]品號類別查詢。空白表篩選分類方式的向下子類別代號。","links":[],"pdfText":"","pdfPages":0,"pdfChars":0,"merged":[],"file":"kb-cards.jsonl"};
