self.KB_CONTENT["card:791718"]={"id":"card:791718","ty":"card","sourceId":"791718","title":"『零用金資料查詢作業』中的『零用金轉撥』為何？","ver":"GP4以上","topic":"單別","keywords":["單別","單號","備註","轉撥"],"y":"other","answer":"* 可查詢該零用金轉撥目前金額。* 轉撥日期、單別、單號、轉撥金額、備註。* 轉撥金額合計=加總 (轉撥金額)。* 轉撥金額，轉撥金額合計。","links":[],"pdfText":"","pdfPages":0,"pdfChars":0,"merged":[],"file":"kb-cards.jsonl"};
