self.KB_CONTENT["card:778643"]={"id":"card:778643","ty":"card","sourceId":"778643","title":"『生產計劃發放作業』中的『選擇製令單別』為何？","ver":"GP4以上","topic":"製令","keywords":["製令","單別","生產","計劃"],"y":"other","answer":"* 可點選(icon)或[F2]單別資料查詢發放所選定的製令單單別。若空白表全部。","links":[],"pdfText":"","pdfPages":0,"pdfChars":0,"merged":[],"file":"kb-cards.jsonl"};
